<?php
namespace App\Http\Controllers;use App\Services\ResourceDraftService;use Illuminate\Http\Request;
final class ResourceDraftController extends Controller{public function __construct(private ResourceDraftService $drafts,private \App\Services\ResourceDraftApplyService $apply){}public function show(Request $r,string $type,string $resource){return ['draft'=>$this->drafts->show($r->user(),$type,$resource)];}public function store(Request $r,string $type,string $resource){$d=$r->validate(['base_revision_id'=>['required','integer'],'snapshot'=>['required','array'],'user_id'=>['prohibited'],'created_by'=>['prohibited']]);return $this->drafts->save($r->user(),$type,$resource,$d['base_revision_id'],$d['snapshot']);}public function apply(Request $r,string $type,string $resource){$r->validate(['force'=>['prohibited'],'merge'=>['prohibited'],'user_id'=>['prohibited'],'base_revision_id'=>['prohibited']]);return $this->apply->apply($r->user(),$type,$resource);}public function destroy(Request $r,string $type,string $resource){$this->drafts->delete($r->user(),$type,$resource);return response()->noContent();}}
